val debouncer = Debouncer<String>(scope = viewModelScope, delay = 300.milliseconds)

// Emit from a text-field's onValueChange:
onValueChange = { text -> debouncer.emit(text) }

// Collect the stable values:
debouncer.flow.collect { stableText -> search(stableText) }

private val searchDebouncer = KDebounce(viewModelScope, 300.milliseconds) { query -> search(query) }

KInput(
    value = searchText,
    onValueChange = { text -> searchText = text; searchDebouncer.emit(text) }
)

private val submitThrottler = Throttler<Unit>(scope = viewModelScope, period = 500.milliseconds)
submitThrottler.onThrottled { submitForm() }

KButton(text = "Submit", onClick = { submitThrottler.emit(Unit) })
